433	/** `m04river`: the wide painted river inside the tunnel — a curved trough (flat lane, sides rising to the walls) carrying
434	 * the approved water design (tile_river3: pink swirl ribbons, cyan streams, foam edges) by arc length across the trough,
435	 * two offset samples blended by slow world-anchored noise (no visible 4.7 u repeat), flowing down the slide, and the
436	 * glowing chevron arrows drawn crisp (distance field) on the centre lane. */
437	const RIVER_VERT = /* glsl */ `
438	uniform mat4 uProjVP;
439	attribute vec2 aR;          // x: signed arc length across the trough (u), y: 0
440	varying vec4 vProj;
441	varying vec3 vL;
442	varying float vS;
443	void main() {
444	  vec4 wp = modelMatrix * vec4(position, 1.0);
445	  vProj = uProjVP * wp;
446	  vL = position;
447	  vS = aR.x;
448	  gl_Position = projectionMatrix * viewMatrix * wp;
449	}`;
450	const RIVER_FRAG = /* glsl */ `
451	uniform sampler2D uPlate;
452	uniform vec4 uPjPost;
453	uniform vec2 uPjRes;
454	uniform float uAway;
455	uniform sampler2D uRiv;
456	uniform vec4 uRivA;          // lateral half-width, along start, along length, lateral scale
457	uniform vec3 uLane;          // r13 m04lane: x on, y clean-lane half width (u), z strength
458	uniform vec2 uLane3;         // r13 m04lcd / m04lcw: deeper blue along the arrow line (strength, half width)
459	uniform vec2 uLane4;         // r14 m04lcn: deep-blue fade-in window ahead of the camera (start, full); off when y <= x
460	uniform vec4 uLane2;         // r13 m04lane2: x swirl detail, y gloss, z sparkle
461	uniform vec4 uEdge;          // r13 m04edge: x on, y half arc to the edge, z fringe width, w strength
462	uniform vec2 uSE;            // r13 m04rse / m04rsl: the climbing side water as long flowing currents (along stretch, from |lat|)
463	uniform float uTime;
464	uniform vec4 uArr;           // arrow spacing, first arrow (along), half width, arm thickness
465	uniform float uZ0;
466	uniform vec4 uPk;            // m04pink: x on, y cyan lane half width, z outer edge of the pink bands, w strength
467	uniform float uPkH;          // r14 m04pkh: pink only where the painted tile is pink (0 = off)
468	uniform sampler2D uSB;       // r15 m04sband: the painted swirl bands (tile_side04: across = lane side .. wall side reversed)
469	uniform vec4 uSB0;           // x strength, y inner |arc| where the bands start, z outer |arc| (water edge), w tile length along (u)
470	uniform vec4 uSB1;           // x blend width at the inner side, y re-apply the lilac-white edge fringe (0/1), z tile part used
471	                             // (1 = cyan..lilac, less = start nearer the pink ribbon), w slow lateral wander of the bands (u)
472	uniform vec2 uSB2;           // far ahead of the camera (x -> y u) the bands smooth into long unbroken stripes (no repeat ribs)
473	uniform vec4 uNB;            // r17 m04nband: x on, y Benny along (local), z Benny lateral, w inner arc hugging Benny (u)
474	uniform vec4 uNB2;           // r17 m04nband: x bands back at the normal inner arc this far ahead of Benny (u), y widening behind Benny (b * d^2; < 0 = straight |b| per u)
475	                             // behind Benny, z extra pinch at Benny's sides (u), w lateral follow of Benny (0..1)
476	uniform vec2 uNB3;           // r17 m04nband: x width of one cyan -> pink half stripe near Benny (u; 0 = one stretched band), y tile span
477	uniform vec4 uNB4;           // r18 m04nwhirl: x along squash of the whirl ellipse behind Benny (0 = off), y its centre ahead of Benny (u),
478	                             // z S-meander amplitude of the band edge ahead of Benny (u, 0 = off), w meander wavelength (u)
479	uniform float uNB5;          // r18 m04nwhirl: spiral twist (stripe periods per half turn round Benny; 0 = closed U rings)
480	uniform vec2 uNB6;           // r18 m04nwhirl: cyan corridor straight behind Benny — x half width (u, 0 = off), y soft edge (u)
481	uniform vec2 uNB7;           // r18 m04nwq / m04nwr: x clean lane water where the whirl leaves the water bare (0/1), y whirl radius
482	                             // round Benny (u; 0 = unlimited) — beyond it the bands run straight again (no smear when the camera lags)
483	uniform vec4 uSS;            // r18 m04sswirl: x swing of the band pattern across the bank (u, 0 = off), y its wavelength along (u),
484	                             // z how far the water's top edge laps back down in tongues (u, 0 = straight edge), w lap wavelength (u)
485	uniform vec4 uA5;          // m04arr5: x on, y spacing, z first apex (along), w bar thickness along the flow
486	uniform vec4 uA5b;           // m04arr5: x half width, y arm slope (along per lateral), z camera along, w visible depth
487	uniform vec2 uA5n;           // r10 m04arr5: near fade-in distance (start, full) ahead of the camera; default 6.5, 9.0
488	varying vec4 vProj;
489	varying vec3 vL;
490	varying float vS;
491	${PROJ05_INVERSE}
492	float h21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
493	float vn(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
494	  return mix(mix(h21(i), h21(i + vec2(1, 0)), f.x), mix(h21(i + vec2(0, 1)), h21(i + vec2(1, 1)), f.x), f.y); }
495	// chevron pointing down the slide: distance to the two arms
496	float chev(vec2 p, float hw, float th) {
497	  p.x = abs(p.x);
498	  vec2 a = vec2(0.0, 0.0), b = vec2(hw, -hw * 2.3);   // long arms along the flow (painted arrows seen low)
499	  vec2 pa = p - a, ba = b - a;
500	  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
501	  return length(pa - ba * h) - th;
502	}
503	void main() {
504	  float along = -vL.z;                                     // down the slide from Benny's checkpoint water point
505	  float flow = along - uTime * 0.9;                        // the design drifts down the slide with the current
506	  float lat = vS * uRivA.w + 0.9 * (vn(vec2(along * 0.07, 7.0)) - 0.5) * smoothstep(0.4, 1.6, abs(vS));
507	  float fl = flow + 2.2 * (vn(vec2(along * 0.05, vS * 0.15 + 1.0)) - 0.5);
508	  float se = 1.0 + (uSE.x - 1.0) * smoothstep(uSE.y, uSE.y + 0.9, abs(vS));
509	  vec2 uv1 = vec2(lat / (2.0 * uRivA.x) + 0.5, (fl - uRivA.y) / (uRivA.z * se));
510	  vec2 uv2 = vec2(-lat / (2.0 * uRivA.x) * 0.96 + 0.5, (fl - uRivA.y) / (uRivA.z * se) * 0.77 + 0.37);
511	  float w = smoothstep(0.3, 0.7, vn(vec2(along * 0.16, vS * 0.35 + 3.0)));
512	  vec3 col = mix(texture2D(uRiv, uv1).rgb, texture2D(uRiv, uv2).rgb, w);
513	  vec3 tileC = col;                                        // r14: the painted tile colour before any re-colouring
514	  vec3 laneCol = col;                                      // r18: the clean lane water (for the bare parts of the whirl)
515	  // the deeper cyan centre lane of the painting
516	  col = mix(col, col * vec3(0.55, 0.85, 1.0) + vec3(0.0, 0.05, 0.12), 0.35 * (1.0 - smoothstep(0.9, 1.7, abs(vS))));
517	  if (uLane.x > 0.5) {
518	    // r13 m04lane: the painted centre path is ONE clean glossy blue lane (deep cyan-blue, soft long light streaks, no
519	    // foam crests or swirl knots): the tile seen heavily smoothed (mip bias) for its gentle light / dark flow, re-coloured
520	    // into the painted lane blues, plus a few long thin highlights running down the path
521	    float kl = 1.0 - smoothstep(uLane.y, uLane.y + 0.9, abs(vS));
522	    vec3 bl = mix(texture2D(uRiv, uv1, 4.5).rgb, texture2D(uRiv, uv2, 4.5).rgb, w);
523	    float lb = dot(bl, vec3(0.30, 0.55, 0.15));
524	    vec3 laneC = mix(vec3(0.02, 0.42, 0.88), vec3(0.30, 0.82, 1.0), smoothstep(0.35, 0.80, lb));
525	    float sk = vn(vec2(vS * 3.1 + 2.0, fl * 0.12));
526	    laneC += vec3(0.55, 0.85, 1.0) * 0.35 * smoothstep(0.80, 0.97, sk);
527	    if (uLane2.x > 0.0) {
528	      // r13 m04lane2: the painted lane as RICH glossy magical water — saturated electric blue -> electric cyan, the tile's
529	      // own swirls kept at a moderate blur (uLane2.x = detail), flowing glossy highlight ribbons, twinkling white sparkles
530	      vec3 dl = mix(texture2D(uRiv, uv1, 1.5).rgb, texture2D(uRiv, uv2, 1.5).rgb, w);
531	      float ld = mix(lb, dot(dl, vec3(0.30, 0.55, 0.15)), uLane2.x) + uLane2.w;   // w = brighter / more turquoise
532	      laneC = mix(vec3(0.00, 0.22, 0.86), vec3(0.00, 0.62, 1.00), smoothstep(0.20, 0.55, ld));
533	      laneC = mix(laneC, vec3(0.16, 0.92, 1.00), smoothstep(0.55, 0.82, ld));
534	      laneC = mix(laneC, vec3(0.80, 0.98, 1.00), uLane2.y * smoothstep(0.84, 0.97, ld));            // glossy crests
535	      float rib = vn(vec2(vS * 2.3 + 5.0, fl * 0.35));                                              // flowing highlight ribbons
536	      laneC += vec3(0.45, 0.85, 1.0) * 0.30 * uLane2.y * smoothstep(0.72, 0.92, rib) * (0.6 + 0.4 * sin(fl * 2.0 + vS));
537	      vec2 sc = vec2(vS * 5.0, fl * 3.0); vec2 si = floor(sc), sf = fract(sc) - 0.5;              // sparkles
538	      float sh = h21(si + 17.0);
539	      float tw = 0.5 + 0.5 * sin(uTime * 6.0 + sh * 40.0);
540	      float spk = smoothstep(0.16, 0.0, length(sf - (vec2(h21(si + 3.1), h21(si + 7.7)) - 0.5) * 0.6)) * step(0.86, sh) * tw;
541	      laneC += vec3(1.0) * uLane2.z * spk * (1.0 - smoothstep(0.3, 0.8, fwidth(sc.x)));
542	      // r13 m04lcd: the painted lane is DEEPER blue along the arrow line (the glassy arrows pop on it), brighter turquoise
543	      // toward the pink edges
544	      // r14 m04lcn=a,b: the deep blue only AHEAD of Benny (fades in from a to b u ahead of the camera; Benny ≈ 6.4 u
545	      // ahead) — the painted water round / behind him is bright cyan, the deep electric blue lies under the arrows
546	      float rk = uLane4.y > uLane4.x ? smoothstep(uLane4.x, uLane4.y, along - uA5b.z) : 1.0;
547	      float wl = rk * (1.0 - smoothstep(0.2, uLane3.y, abs(vS)));
548	      if (uLane4.y > uLane4.x && uLane4.x < 0.0) {
549	        // r14 m04lcn=-a,b (negative start): the PAINTED deep azure keyed on the water's own brightness, so the swirls,
550	        // glossy crests and white glints survive (a plain multiply flattened the lane into a dark royal-blue patch)
551	        float lq = dot(laneC, vec3(0.30, 0.55, 0.15));
552	        vec3 deep = mix(vec3(0.00, 0.40, 0.86), vec3(0.02, 0.66, 0.98), smoothstep(0.40, 0.88, lq));
553	        deep = mix(deep, laneC, smoothstep(0.90, 0.99, lq));                                     // keep only the white glints
554	        laneC = mix(laneC, deep, min(uLane3.x, 1.0) * smoothstep(-uLane4.x, uLane4.y, along - uA5b.z) * (1.0 - smoothstep(0.2, uLane3.y, abs(vS))));
555	      } else {
556	        laneC = mix(laneC, laneC * vec3(0.42, 0.70, 1.0), uLane3.x * wl);
557	      }
558	    }
559	    laneCol = laneC;
560	    col = mix(col, laneC, kl * uLane.z);
561	  }
562	  float fringe = 0.0, edgeY = uEdge.y;
563	  if (uSS.z > 0.0) {
564	    // r18 m04sswirl: the water's top edge against the gold wall laps up and down in soft tongues (painted: no straight
565	    // hard line where the water meets the wall); the lilac fringe follows the lapping edge
566	    float lw = 0.5 + 0.5 * sin(along * 6.2832 / uSS.w + (vS < 0.0 ? 0.7 : 2.9));
567	    lw = 0.65 * lw + 0.35 * vn(vec2(along * 0.8, vS < 0.0 ? 3.0 : 9.0));
568	    edgeY = uEdge.y - uSS.z * lw;
569	    if (abs(vS) > edgeY) discard;
570	  }
571	  if (uEdge.x > 0.5) {
572	    // r13 m04edge: soft irregular water edge against the gold wall — pink / magenta current then a lilac-white lacy fringe
573	    // in broken patches (no straight hard line, no tall foam): uEdge.y = half arc to the edge, z = fringe width, w = strength
574	    float e = smoothstep(edgeY - uEdge.z, edgeY - 0.04, abs(vS));
575	    float n1 = vn(vec2(fl * 0.9, sign(vS) * 7.0 + abs(vS) * 2.0)), n2 = vn(vec2(fl * 2.7 + 3.0, abs(vS) * 6.0));
576	    float patchy = smoothstep(0.35, 0.75, 0.65 * n1 + 0.35 * n2);
577	    vec3 pinkC = mix(vec3(0.78, 0.16, 0.66), vec3(1.0, 0.45, 0.82), n2);
578	    col = mix(col, pinkC, uEdge.w * smoothstep(edgeY - uEdge.z * 2.2, edgeY - uEdge.z, abs(vS)) * (0.5 + 0.5 * n1));
579	    fringe = uEdge.w * e * patchy;
580	    col = mix(col, vec3(0.97, 0.90, 1.0), fringe);
581	  }
582	  if (uPk.x > 0.5) {
583	    // m04pink: the painted broad pink / magenta swirl bands either side of the cyan lane; the swirl structure (the
584	    // tile's brightness) is kept, re-coloured into the painted magenta -> hot pink -> pale pink, with cyan streaks left
585	    float side = smoothstep(uPk.y, uPk.y + 0.7, abs(vS)) * (1.0 - smoothstep(uPk.z, uPk.z + 0.9, abs(vS)));
586	    float l = dot(col, vec3(0.30, 0.55, 0.15));
587	    vec3 pk = mix(vec3(0.55, 0.08, 0.58), vec3(0.96, 0.30, 0.78), smoothstep(0.22, 0.58, l));
588	    pk = mix(pk, vec3(1.0, 0.78, 0.96), smoothstep(0.66, 0.95, l));
589	    float n = vn(vec2(fl * 0.22, vS * 0.6 + 11.0));
590	    float keepCyan = smoothstep(0.62, 0.85, n);                       // a few cyan swirls survive inside the pink
591	    float pkMix = 1.0 - 0.75 * keepCyan;
592	    if (uPkH > 0.0) {
593	      // r14 m04pkh=x: the PAINTED band structure — re-colour only where the painted tile itself is pink / magenta (red
594	      // above green); its cyan streaks between the satin bands stay cyan (x = how strictly; 0 = old uniform pink)
595	      float pinkness = smoothstep(-0.04, 0.22, tileC.r - tileC.g);
596	      pkMix = mix(pkMix, 0.12 + 0.88 * pinkness, uPkH);
597	    }
598	    col = mix(col, pk, side * uPk.w * pkMix);
599	  }
600	  if (uSB0.x > 0.0) {
601	    // r15 m04sband: the side water carries the PAINTED swirl bands (cyan streaks by the lane -> violet -> hot-pink satin
602	    // ribbon -> lilac sparkle at the wall), cut from references/04 (tools/match04/sideband04.py), by arc length across the
603	    // trough and world position along it (flowing with the current), two offset samples blended like the river tile
604	    float inner = uSB0.y, sv = vS, rr = -1.0, mea = 0.0, twp = 0.0, ckc = 1.0;
605	    if (uNB.x > 0.5) {
606	      // r17 m04nband: the painted bands sweep in close round Benny (inner edge hugging him at his position and behind
607	      // him toward the camera) and curve back out to the normal lane width ahead of him (arrow lane stays cyan); the band
608	      // pixels stay world-anchored and flowing, only where they start follows Benny down the slide
609	      float d = along - uNB.y;
610	      sv = vS - uNB.z * uNB2.w;
611	      float db = max(-d, 0.0), hug = uNB.w + uNB2.y * (uNB2.y < 0.0 ? -db : db * db) - uNB2.z * exp(-d * d / 1.2);  // < 0: straight widening
612	      if (uNB4.x > 0.0) {
613	        // r18 m04nwhirl: as painted, the bands WRAP round Benny like a whirl — behind him (toward the camera) they no longer
614	        // open outward but close in under him: the band edge is an ellipse centred on Benny (cyan pocket + splash round
615	        // him), so the pink / cyan stripes curve in from both sides and cross under him in crescents
616	        hug = uNB.w - uNB2.z * exp(-d * d / 1.2);
617	        float fo = mix(1.0, uNB2.w, smoothstep(0.0, uNB2.x, d));            // centred on Benny at / behind him
618	        vec2 wq = vec2(vS - uNB.z * fo, uNB4.x * min(d - uNB4.y, 0.0));
619	        rr = length(wq);
620	        float wf = uNB7.y > 0.0 ? 1.0 - smoothstep(uNB7.y - 1.0, uNB7.y, rr) : 1.0;   // r18 m04nwr: whirl only near Benny
621	        // spiral, not closed rings: a stripe hugging Benny's left side sweeps under him and comes out farther out on his
622	        // right (uNB5 stripe periods per half turn; whole numbers leave the bands ahead of him unchanged)
623	        twp = uNB5 * 2.0 * uNB3.x * abs(atan(wq.y, wq.x)) / 3.14159 * wf;
624	        // as painted, the water right round and straight below Benny stays cyan (white splash); the pink sweeps in from the
625	        // lower-left / lower-right and fades out before the middle (no magenta pool under him)
626	        if (uNB6.x > 0.0) ckc = 1.0 - smoothstep(uNB4.y, uNB4.y - 1.0, d) * (1.0 - smoothstep(uNB6.x - uNB6.y, uNB6.x, abs(wq.x)));
627	        // r18 m04nwq: where the whirl leaves the water bare (pocket / corridor round Benny) show the clean glossy lane water, not
628	        // the raw painted tile magnified into big white cloud blobs (seen beside Benny while he steers to the side)
629	        if (uNB7.x > 0.5) {
630	          // m04nwq=2: the painted cyan streaks of the band strip's lane side instead (crisp at any distance, flowing along)
631	          vec3 bare = laneCol;
632	          if (uNB7.x > 1.5) {
633	            // walk across the cyan part of the strip with the lateral position and offset each lane along, so the streaks
634	            // run with the flow side by side (one column alone gives bands straight across the river)
